#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>

#define MAX_VALUE 0xBFA17DC6ULL   /* 3 215 031 750 – the limit used by the binary */
#define NUM_BASES 6

/* bases that make Miller–Rabin deterministic for 32‑bit numbers */
static const uint32_t bases[NUM_BASES] = {2, 3, 5, 7, 11, 13};

/* (a * b) % mod using 64‑bit intermediate to avoid overflow */
static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    return (a * b) % mod;
}

/* (base ^ exp) % mod – binary exponentiation */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;

    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* deterministic Miller–Rabin for n ≤ 0xBFA17DC6 */
static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;
    if (n == 2 || n == 3)
        return 1;
    if ((n & 1) == 0)               /* even numbers > 2 are composite */
        return 0;

    /* write n‑1 = d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < NUM_BASES; ++i) {
        uint64_t a = bases[i];
        if (a % n == 0)               /* base is a multiple of n → skip */
            continue;

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;                 /* this base passes */

        int passed = 0;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                passed = 1;
                break;
            }
        }
        if (!passed)
            return 0;                 /* composite */
    }
    return 1;                         /* deterministic for this range */
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long val = strtoll(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (val < 0) {
        puts("NOT_PRIME");
        return 0;
    }

    uint64_t n = (uint64_t)val;

    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
